// ── 根据 domain 匹配最佳模板 ──
function getTemplateForDomain(domain) {
  if (!domain) return null
  const d = domain.toLowerCase()
  for (const [key, tmpl] of Object.entries(CODE_TEMPLATES)) {
    if (tmpl.domain.some(dm => d.includes(dm) || dm.includes(d))) {
      return { key, template: tmpl }
    }
  }
  return null
}


